problems.solution:
def count_pairs(a, t):
    seen = {}
    pairs = 0
    for v in a:
        pairs += seen.get(t - v, 0)
        seen[v] = seen.get(v, 0) + 1
    return pairs

problems.brute:
def count_pairs(a, t):
    n = len(a)
    return sum(1 for i in range(n) for j in range(i + 1, n) if a[i] + a[j] == t)

